#!/bin/sh
# Revisa solo los archivos .js que se van a commitear
archivos=$(git diff --cached --name-only --diff-filter=ACMR | grep -E '\.js$' || true)
[ -z "$archivos" ] && exit 0
echo "pre-commit: reviso $archivos"
npx eslint $archivos || { echo "pre-commit: ESLint encontró errores, no se hizo el commit"; exit 1; }
npx prettier --check $archivos || { echo "pre-commit: Prettier encontró archivos sin formato, no se hizo el commit"; exit 1; }
